#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main() {
   int pipefd[2]; // file descriptor array for pipe
   pid_t child_pid; // process id
   if (pipe(pipefd) == -1) { // create pipe and check for errors
      perror("pipe error");
      exit(EXIT_FAILURE);
   }
   child_pid = fork(); // create child process
   if (child_pid == -1) {
      perror("fork error");
      exit(EXIT_FAILURE);
   }
   if (child_pid == 0) { // child process
      pid_t child_process_id = getpid(); // get child process id
      close(pipefd[0]); // close read end of pipe
      if (write(pipefd[1], &child_process_id, sizeof(child_process_id)) == -1) {
         perror("write error");
         exit(EXIT_FAILURE);
      }
      close(pipefd[1]);
   }
   else { // parent process
      pid_t child_process_id;
      close(pipefd[1]); // close write end of pipe
      if (read(pipefd[0], &child_process_id, sizeof(child_process_id)) == -1) {
         perror("read error");
         exit(EXIT_FAILURE);
      }
      close(pipefd[0]);
      printf("Parent (pid=%d):Received Child Process ID is %d\n",getpid(),
child_process_id);
      printf("Parent (pid=%d):Parent Process ID is %d\n", getpid(),getpid());

    }
    return 0;
}

